import numpy as np

def overlap_returns(r, J, K):
    T = r.shape[0]
    f = formation_returns(r, J)
    out = []
    for s in range(J, T - K + 1):
        w = cohort_weights(f[s])
        out.append(sum(w @ r[s + h] for h in range(K)))
    return np.array(out)

