import numpy as np

def nw_t_by_hand(x, lags):
    x = np.asarray(x, dtype=float)
    n = len(x)
    u = x - x.mean()
    V = np.sum(u * u) / n
    for j in range(1, lags + 1):
        gamma = np.sum(u[j:] * u[:-j]) / n
        V += 2 * (1 - j / (lags + 1)) * gamma
    return float(x.mean() / np.sqrt(V / n))
